import React, { useRef, useState } from 'react';
import FilePreview from './FilePreview';

// Composer: multi-file drag-and-drop + hashtag parsing + preview grid
// Props: onSubmit({ author, text, files: [ { dataUrl, type } ], tags })

export default function Composer({ onSubmit, initialAuthor = '' }) {
  const fileInputRef = useRef();
  const [author, setAuthor] = useState(initialAuthor);
  const [text, setText] = useState('');
  const [files, setFiles] = useState([]); // { dataUrl, type }
  const [dragOver, setDragOver] = useState(false);

  const readFileAsDataURL = (file) => new Promise((res, rej) => {
    const reader = new FileReader();
    reader.onload = () => res(reader.result);
    reader.onerror = rej;
    reader.readAsDataURL(file);
  });

  const handleFiles = async (fileList) => {
    const arr = Array.from(fileList);
    const processed = await Promise.all(arr.map(async (f) => {
      const dataUrl = await readFileAsDataURL(f);
      const type = f.type.startsWith('video') ? 'video' : 'image';
      return { dataUrl, type, name: f.name };
    }));
    setFiles(prev => [...prev, ...processed]);
  };

  const onDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    if (e.dataTransfer && e.dataTransfer.files) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const onFileChange = (e) => {
    if (e.target.files) handleFiles(e.target.files);
  };

  const removeFile = (index) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const updateFile = (index, newDataUrl) => {
    setFiles(prev => prev.map((f, i) => (i === index ? { ...f, dataUrl: newDataUrl } : f)));
  };

  const parseTags = (text) => {
    const tags = new Set();
    const regex = /#([a-zA-Z0-9\u3131-\uD79D_-]+)/g;
    let m;
    while ((m = regex.exec(text))) {
      tags.add(m[1].toLowerCase());
    }
    return Array.from(tags);
  };

  const handleSubmit = async (e) => {
    e && e.preventDefault();
    if (!author.trim() || !text.trim()) return alert('작성자와 내용을 입력해주세요');
    const tags = parseTags(text);
    await onSubmit({ author: author.trim(), text: text.trim(), files, tags });
    setText('');
    setFiles([]);
  };

  return (
    <div style={{ border: '1px solid #eee', padding: 12, borderRadius: 10, background: '#fff' }}>
      <form onSubmit={handleSubmit}>
        <div style={{ display: 'flex', gap: 8, marginBottom: 8 }}>
          <input placeholder="작성자" value={author} onChange={(e) => setAuthor(e.target.value)} style={{ flex: '0 0 160px', padding: 8, borderRadius: 8, border: '1px solid #ddd' }} />
          <textarea placeholder="무슨 생각을 하고 계신가요? #태그를 사용해보세요" value={text} onChange={(e) => setText(e.target.value)} style={{ flex: 1, padding: 10, borderRadius: 12, border: '1px solid #e6eefb', minHeight: 100, boxShadow: 'inset 0 1px 0 rgba(11,87,164,0.03)' }} />
        </div>

        <div onDrop={onDrop} onDragOver={(e) => { e.preventDefault(); setDragOver(true); }} onDragLeave={() => setDragOver(false)} style={{ border: `2px dashed ${dragOver ? 'var(--primary)' : '#eee'}`, padding: 12, borderRadius: 8, marginBottom: 8, textAlign: 'center', background: dragOver ? '#f2f8ff' : 'transparent', cursor: 'pointer' }} onClick={() => fileInputRef.current && fileInputRef.current.click()}>
          <div style={{ color: '#666' }}>이미지/동영상을 드래그하거나 클릭하여 업로드하세요 (최대 8개)</div>
          <input ref={fileInputRef} type="file" multiple accept="image/*,video/*" onChange={onFileChange} style={{ display: 'none' }} />
        </div>

        {files.length > 0 && (
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: 8, marginBottom: 8 }}>
            {files.map((f, i) => (
              <FilePreview key={i} file={f.dataUrl} type={f.type} index={i} onRemove={removeFile} onUpdate={updateFile} />
            ))}
          </div>
        )}

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div style={{ color: '#999', fontSize: 12 }}>{files.length} files</div>
          <div>
            <button type="button" onClick={() => { setText(''); setFiles([]); }} style={{ marginRight: 8, padding: '8px 12px', borderRadius: 8, border: '1px solid #ddd', background: '#fff' }}>초기화</button>
            <button type="submit" className="btn btn-primary" style={{ padding: '8px 14px', borderRadius: 10, border: 'none' }}>게시하기</button>
          </div>
        </div>
      </form>
    </div>
  );
}
